<script setup lang="ts">
import {ref} from 'vue'
import PageShell from '../../../components/PageShell.vue'
import AppIcon from '../../../components/AppIcon.vue'
import StatePanel from '../../../components/StatePanel.vue'
import {doctorApi} from '../../../api/doctor'
import {useUserStore} from '../../../stores/user'
import {usePageData} from '../../../utils/usePageData'
import {go} from '../../../utils/navigation'
import type {Dashboard,Report} from '../../../types'
const store=useUserStore(),data=ref<Dashboard>(),reports=ref<Report[]>([])
const {loading,error,load}=usePageData('doctor',async()=>{[data.value,reports.value]=await Promise.all([doctorApi.dashboard(),doctorApi.reviews()])})
const stats=[{key:'workers' as const,label:'授权管理职工',icon:'users',url:'/pages/doctor/workers/index',tone:'green'},{key:'pendingReviews' as const,label:'待审核报告',icon:'clipboard-check',url:'/pages/doctor/reviews/index',tone:'amber'},{key:'followups' as const,label:'待随访任务',icon:'calendar-check',url:'/pages/doctor/followups/index',tone:'teal'},{key:'alerts' as const,label:'风险提示',icon:'triangle-alert',url:'/pages/doctor/workers/index',tone:'orange'}]
</script>
<template><PageShell title="医生工作台" tab="dashboard" doctor :back="false"><view class="doctor-hero"><view class="flex gap"><image class="avatar" src="/static/doctor.png"/><view class="grow"><text class="doctor-name">{{store.profile?.name}}<text>职业健康科</text></text><text class="doctor-org">{{store.profile?.institution}}</text></view><view class="hero-badge"><AppIcon name="shield-check" color="white" :size="22"/></view></view><text class="doctor-slogan">专业守护，让健康管理更有温度</text></view><view class="content dashboard-content"><StatePanel :loading="loading" :error="error" @retry="load"/><template v-if="data"><view class="card stats-grid"><view v-for="s in stats" :key="s.key" @tap="go(s.url)"><view class="stat-icon" :class="s.tone"><AppIcon :name="s.icon" :size="26"/></view><view class="grow"><text class="stat-value">{{data[s.key]}}</text><text class="stat-label">{{s.label}}</text></view><AppIcon name="chevron-right" color="gray" :size="14"/></view></view><view class="section-head" style="margin:32rpx 0 20rpx"><text class="section-title">今日待办</text><text class="more">按授权范围展示</text></view><view class="card task-card"><view v-for="(t,i) in data.tasks" :key="t.title" class="row" @tap="go(t.url)"><view class="list-icon"><AppIcon :name="i===0?'clipboard-check':'calendar-check'" :size="22"/></view><text class="row-label">{{t.title}}</text><text class="task-count">{{t.count}}</text><AppIcon name="chevron-right" color="gray" :size="15"/></view></view><view class="section-head" style="margin:30rpx 0 20rpx"><text class="section-title">优先关注</text><text class="more" @tap="go('/pages/doctor/reviews/index')">全部报告 ›</text></view><view v-for="r in reports.filter(r=>r.status==='pending').slice(0,2)" :key="r.id" class="card priority" @tap="go('/pages/doctor/review-detail/index?id='+r.id)"><view class="flex gap"><image class="priority-avatar" src="/static/miner.png"/><view class="grow"><text class="bold">{{r.workerName}}</text><view class="help">{{r.employeeNo}} · {{r.date}}</view></view><text class="tag tag-amber">待审核</text></view><view class="priority-footer"><AppIcon name="scan-text" :size="17"/><text>待核对 {{r.fields.filter(f=>f.needsConfirm).length}} 项提取字段</text><AppIcon name="chevron-right" color="gray" :size="16"/></view></view><view class="hint flex gap"><AppIcon name="shield-check" :size="23"/><text>每一份审核，都为矿山职工多一份安心</text></view></template></view></PageShell></template>
<style scoped>.doctor-hero{background:linear-gradient(110deg,#00834e,#009a61);color:white;padding:35rpx 35rpx 82rpx;border-radius:0 0 40rpx 40rpx}.doctor-name{font-size:37rpx;font-weight:650;display:block}.doctor-name text{font-size:22rpx;margin-left:18rpx;opacity:.8;font-weight:400}.doctor-org{font-size:22rpx;opacity:.75;display:block;margin-top:7rpx}.hero-badge{padding:18rpx;background:#ffffff15;border-radius:18rpx}.doctor-slogan{display:block;font-size:22rpx;letter-spacing:2rpx;margin-top:25rpx;opacity:.7}.dashboard-content{margin-top:-55rpx;position:relative}.stats-grid{display:flex;flex-wrap:wrap;padding:14rpx}.stats-grid>view{width:50%;padding:22rpx 14rpx;display:flex;align-items:center;gap:14rpx}.stat-icon{padding:17rpx;background:#e8f6ed;border-radius:18rpx;display:flex}.stat-icon.amber{background:#fff3df}.stat-icon.teal{background:#e8f5f3}.stat-icon.orange{background:#fff0e7}.stat-value{font-size:42rpx;font-weight:700;display:block;line-height:1.2}.stat-label{font-size:21rpx;color:#7c9383;display:block;margin-top:7rpx}.task-card{padding:0 26rpx}.task-count{font-size:25rpx;color:#008f55;background:#eef8f1;border-radius:10rpx;min-width:45rpx;text-align:center;padding:3rpx 8rpx}.priority-avatar{height:72rpx;width:72rpx;border-radius:50%}.priority-footer{margin-top:24rpx;border-top:1px solid #f0f3f0;padding-top:20rpx;display:flex;gap:14rpx;align-items:center;font-size:23rpx;color:#7e9784}.priority-footer>text{flex:1}</style>
